For finite $A \subset \mathbb{Z}^d$, we define the harmonic measure of $y$ in $A$ as a limit of conditional hitting probabilities of $A$:
\begin{equation} \mathbb{H}_A (y) = \lim_{\| x \| \to \infty} \mathbb{P}_x (S_{\tau_A} = y \mid \tau_A < \infty ).
\end{equation}

We define $\theta$ in terms of two sequences of random times, $(\tau_i)_{i \geq 1}$ and $(\xi_i)_{i \geq 0}$. In words, $\tau_i$ is the first time $t \geq \xi_{i-1}$ at which $U_t$ has an $(\alpha,b)$ DOT clustering in $\mathrm{Ref}^\times$, and $\xi_i$ is the first time $t > \tau_i$ at which the natural clustering $(\mathcal{U}_t)_{t \geq \tau_i}$ of $(U_t)_{t \geq \tau_i}$ with $\psi (U_{\tau_i})$ is not a $(g(t-\tau_i),b)$ DOT clustering of $U_t$. More precisely, we define $\xi_0 = 0$ and, for $i \geq 1$,  
\begin{align*}
\tau_i &=  \inf \left\{t \geq \xi_{i-1}: \mathrm{Clust}_{\alpha,b}^\bullet (U_t) \cap \mathrm{Ref}^\times \neq \emptyset \right\}, \quad \text{and}\\ 
\xi_i &= \inf \left\{t > \tau_i: \mathcal{U}_t \notin \mathrm{Clust}_{ g(t-\tau_i),b}^\bullet (U_{t}) \right\}.
\end{align*}
Lastly, we define $\theta = \tau_I$ for $I = \inf \{i \geq 1: \tau_i < \infty, \xi_i = \infty\}$.

The harmonic measure of $A$ equals
\begin{equation*}
\mathbb{H}_A (x) = \frac{\mathrm{esc}_A (x)}{\mathrm{cap}_A}, \quad x \in \mathbb{Z}^d.
\end{equation*}
For a proof of this fact, see \cite[Theorem 2.1.3]{lawler2013intersections}.

To interpret $\mathbb{H}_{\mathcal{A}} (i,x)$, note that the harmonic measure of $\mathcal{A}$ at $(i,x)$ is equal to the harmonic measure of $\mathcal{A}^i$ at $x$, weighted by the ratio of the capacities of $\mathcal{A}^i$ and $\mathcal{A}$:
\begin{equation} \mathbb{H}_{\mathcal{A}} (i,x) = \frac{\mathrm{cap}_{\mathcal{A}^i}}{\mathrm{cap}_{\mathcal{A}}} \, \mathbb{H}_{\mathcal{A}^i} (x).
\end{equation}

Our basic tool is Green's function $G(x)$, which is defined in $d \geq 3$ dimensions as the expected number of visits to $x$ by random walk from the origin: 
\begin{equation} G(x) = \mathbb{E}_o \left[ \sum_{j=0}^\infty \mathbf{1} (S_j = x) \right], \quad x \in \mathbb{Z}^d.
\end{equation}

Let $x \in U$. We can express $\mathrm{esc}_U (x)$ in terms of $N = \sum_{j=1}^\infty \mathbf{1} (S_j \in U)$, the number of returns made to $U$ by random walk, as 
\begin{equation} \mathrm{esc}_U (x) = \mathbb{P}_x (N=0) = 1 - \frac{\mathbb{E}_x [N]}{\mathbb{E}_x [N \mid N > 0]}.
\end{equation}

To bound below $\mathbb{E}_x [N \mid N>0]$, we use the fact that $\mathbb{E}_z [N] \geq G(o) - 1$ for every $z \in U$, since $N$ is at least the number of times that random walk returns to $z$. Consequently, 
\begin{align*}
\mathbb{E}_x [N \mid N > 0] & = 1 + \mathbb{E}_x \big[ \mathbb{E}_{S_{\tau_{U}}} [N] \bigm\vert \tau_{U} < \infty \big] \geq G(o).
\end{align*}

Let $U$ and $\mathcal{P}$ satisfy the hypotheses and let $x \in \mathcal{P}^1$. We bound below $\mathrm{esc}_U (x)$ as
\begin{align*}
\mathrm{esc}_U (x) &= \mathrm{esc}_{\mathcal{P}^1} (x) - \mathbb{P}_x (\tau_{\mathcal{P}^1} = \infty, \tau_{\mathcal{P}^2} < \infty)\\ 
&\geq \left(1 - \frac{\mathbb{P}_x (\tau_{\mathcal{P}^2} < \infty)}{\mathrm{esc}_{\mathcal{P}^1} (x)} \right) \mathrm{esc}_{\mathcal{P}^1} (x) \geq \left(1 - O \left( |U| \mathrm{sep} (\mathcal{P}^{2-d}) \right) \right) \mathrm{esc}_{\mathcal{P}^1} (x).
\end{align*}

Let $U$ and $\mathcal{P}$ satisfy the hypotheses, and let $x \in \mathcal{P}^1$ and $y \in \partial A$. We bound the probability in \eqref{help est1} as
\begin{align*}
\mathbb{P}_{x} (S_{\tau_A - 1} = y, \tau_{\mathcal{P}^2} < \tau_A < \infty)
&\leq \mathbb{P}_x (\tau_{\mathcal{P}^2} < \tau_A < \infty)\\ 
&\leq \mathbb{P}_x (\tau_{\mathcal{P}^2} < \infty) \max_{z \in \mathcal{P}^2} \mathbb{P}_z ( \tau_A < \infty) \lesssim |U| \mathrm{sep} (\mathcal{P})^{4-2d}.
\end{align*}

We bound below the probability in \eqref{help est2} using the fact (see, e.g., \cite[Exercise 3.25]{popov2021}) that there is a constant $\lambda > 1$ such that, if the distance between $u \in \mathbb{Z}^d$ and a finite set $B \subset \mathbb{Z}^d$ is at least $\lambda \mathrm{diam} (B)$, then 
\begin{equation} \mathbb{P}_u (S_{\tau_B} = v \mid \tau_B < \infty) \geq \frac12 \mathbb{H}_B (v), \quad v \in B.
\end{equation}

To bound below (\ref{inc hat1}a), note that $\tau = \min \{\tau_A, \tau_{\mathcal{C}^2}\}$, so lower and upper bounds of $\mathbb{P}_x (\tau_A < \infty) \geq p_1$ and $\mathbb{P}_x (\tau_{\mathcal{C}^2} < \infty) \leq p_2$ for some $p_1, p_2 \in (0,1]$ would imply that
\begin{equation} \frac{\mathbb{P}_{x} (\tau_A < \infty)}{\mathbb{P}_{x} (\tau < \infty)} \geq \frac{\mathbb{P}_{x} (\tau_A < \infty)}{\mathbb{P}_{x} (\tau_A < \infty) + \mathbb{P}_x (\tau_{\mathcal{C}^2} < \infty)} \geq 1 - \frac{p_2}{p_1}.
\end{equation}

We take $p_1$ and $p_2$ to be the preceding lower and upper bounds (including the implicit constants). Substituting these choices into \eqref{618a bd} yields


\begin{equation*}
\frac{\mathbb{P}_{x} (\tau_A < \infty)}{\mathbb{P}_{x} (\tau < \infty)} \geq 1 - c_1 b^{d-2} |U| \left( \frac{\log \mathrm{sep} (\mathcal{C})}{\mathrm{sep} (\mathcal{C})} \right)^{d-2},
\end{equation*}
for a constant $c_1 = c_1 (d)$.

For $\delta \in (0,\frac12)$, we define the following set of infinite sequences of $(a,b)$ DOT clusterings:
\begin{equation} \mathrm{Grow}_{a,b,\delta} = \left\{ (\mathcal{C}_t)_{t \geq 0} \in (\mathrm{Clust}_{a,b}^\bullet)^{\mathbb{N}}: \mathrm{sep} (\mathcal{C}_t) \geq t^{\frac12-\delta} \,\,\text{for every $t \geq 0$} \right\}.
\end{equation}

If $(\mathcal{D}_s)_{s \geq 0} \in \mathrm{Grow}_{a,b,\delta}$, then $g(t)$ is a lower bound on the separation of $\mathcal{D}_t$, so the Markov property and the one-step approximation (Proposition~\ref{p to q}) imply that $h(t)$ satisfies
\begin{equation} \mathbf{P}_{\mathcal{C}_0} \left( \mathcal{U}_s = \mathcal{D}_s, s \leq t \right) \geq h(t) \mathbf{Q}_{\mathcal{C}_0} \left( \mathcal{V}_s = \mathcal{D}_s, s \leq t \right).
\end{equation}

For $A \subseteq \mathbb{Z}^d$, we define the $\ast$-visible boundary $\partial_{\mathrm{vis}} A$ as
\begin{multline} \partial_{\mathrm{vis}} A = \big\{x \in \mathbb{Z}^d: \text{$x$ is adjacent in $\mathbb{Z}^{d\ast}$ to some $y \in A$}\\ \text{and there is a path from $\infty$ to $x$ disjoint from $A$} \big\}.
\end{multline}

{\bf Fact 2}.\ If $\mathrm{sep} (\mathcal{C})$ is at least $\max\{e^{2b},8\sqrt{d}\}$, then each $\partial_{\mathrm{vis}} F_j$ is disjoint from $\cup_k F_k$. To see why, note that any element of $\partial_{\mathrm{vis}} F_j$ is within $\sqrt{d}$ of an element of $F_j$, while the distance between distinct $F_j$ and $F_k$ exceeds $\sqrt{d}$:
\begin{align*}
\mathrm{dist} (F_j,F_k) & \geq \mathrm{dist}(\mathcal{C}^j,\mathcal{C}^k) - \mathrm{diam} (\mathcal{C}^j) - \mathrm{diam} (\mathcal{C}^k)  - 2\sqrt{d}\\ 
& \geq \mathrm{dist} (\mathcal{C}^j,\mathcal{C}^k) \Big( 1 - \frac{2b \log \mathrm{dist} (\mathcal{C}^j,\mathcal{C}^k) + 2\sqrt{d}}{\mathrm{dist} (\mathcal{C}^j,\mathcal{C}^k)} \Big) > \sqrt{d}. 
\end{align*}
The first inequality follows from the triangle inequality; the second from the fact that $\mathcal{C}$ is a $(\cdot,b)$ clustering; the third from the fact that the ratio is decreasing in $\mathrm{dist} (\mathcal{C}^j, \mathcal{C}^k)$, which is at least $\mathrm{sep} (\mathcal{C})$, and some simple algebra using the assumption that $\mathrm{sep} (\mathcal{C}) \geq \max\{e^{2b},8\sqrt{d}\}$.

Observe that 
\begin{subnumcases}{p_{U_0} (x,y) > 0 \iff}
\mathrm{esc}_{U_0} (x) > 0, \\ 
\mathrm{esc}_{U_1} (y) > 0, \,\,\text{and} \\ 
y \in \partial \big( U_0 {\setminus} \{x\} \big). \end{subnumcases}

Analogously, 
\begin{subnumcases}{q_{\mathcal{C}_0} (i,x,y) > 0 \iff}
\mathrm{esc}_{\mathcal{C}_0^i} (x) > 0, \\ 
\mathrm{esc}_{\mathcal{C}_1^i} (y) > 0, \,\,\text{and} \\ 
y \in \partial \big( \mathcal{C}_0^i {\setminus} \{x\} \big). \end{subnumcases}

Since $\mathcal{C}_0$ is a DOT clustering with a separation of at least $a \geq \kappa$, Propositions~\ref{prop h comp} and \ref{prop t comp} together imply that there is a constant $c = c (b,d,n)$ such that 
\begin{equation} p_{U_0} (x,y) \geq \left(1 - c \left( a^{-1} \log a \right)^{d-2} \right) q_{\mathcal{C}_0} ([x]_{\mathcal{C}_0},x,y).
\end{equation}

For every distinct pair of clusters $i, j \in \{1, \dots, \# \mathcal{V}_0\}$ with $i < j$, we define a random walk $(S_k^{i,j})_{k \geq 0}$ by 
\begin{equation} S_0^{i,j} = M_{\xi_0}^i - M_{\xi_0}^j \quad \text{and} \quad S_k^{i,j} = S_{k-1}^{i,j} + \left( M_{\xi_k}^i - M_{\xi_k}^j - \left( M_{\xi_{k-1}}^i + M_{\xi_{k-1}}^j\right) \right), \quad k \geq 1.
\end{equation}

The triangle inequality implies that
\begin{equation} \left| \mathrm{dist} (\mathcal{V}_t^i, \mathcal{V}_t^j) - \| M_t^i - M_t^j\| \right| \leq \mathrm{diam} (\mathcal{V}_t^i) + \mathrm{diam} (\mathcal{V}_t^j), \quad t \geq 0.
\end{equation}

First, at most one cluster diameter and representative element $M_t^i$ change with each step and, when they do, they change by at most $1$ and $\mathrm{diam} (\mathcal{V}_t^i)$, respectively. In other words, for $t \geq 0$,
\begin{align}
\|M_{t+1}^i - M_t^i\| + \|M_{t+1}^j - M_t^j\| &\leq \max \{ \mathrm{diam} (\mathcal{V}_t^i), \mathrm{diam} (\mathcal{V}_t^j) \}, \\
\mathrm{diam} (\mathcal{V}_{t+1}^i) + \mathrm{diam} (\mathcal{V}_{t+1}^j) &\leq \mathrm{diam} (\mathcal{V}_t^i) + \mathrm{diam} (\mathcal{V}_t^j) + 1. \end{align}

Assume that $\xi_m \leq t < \xi_{m+1}$. By \eqref{tri app both},
\begin{equation} \mathrm{dist} (\mathcal{V}_t^i, \mathcal{V}_t^j) \geq \|M_t^i - M_t^j\| - \mathrm{diam} (\mathcal{V}_t^i) - \mathrm{diam} (\mathcal{V}_t^j).
\end{equation}

To replace $M_t^i - M_t^j$ by $S_m^{i,j} = M_{\xi_m}^i - M_{\xi_m}^j$ in \eqref{tri app}, we bound the norm of their difference:
\begin{equation} M_t^i - M_t^j - (M_{\xi_m}^i - M_{\xi_m}^j) = \sum_{s = \xi_m}^{t-1} \left( M_{s+1}^i - M_{s+1}^j - (M_s^i - M_s^j) \right).
\end{equation}

By Proposition 2.4.5 of \cite{lawler2010random}, there are constants $\gamma_2, \gamma_3 > 0$ such that for every $\mathcal{C}_0 \in \mathrm{Ref}^\times$, every distinct pair $i < j$ of clusters in $\mathcal{C}_0$, and every $r, \lambda > 0$, 
\begin{equation} \mathbf{Q}_{\mathcal{C}_0} (T^{i,j}_{B(r)^{\mathsf{c}}} > \lambda r^2 ) \leq \gamma_2 e^{-\gamma_3 \lambda }.
\end{equation}

Furthermore, by Proposition 6.4.2 of \cite{lawler2010random}, there are constants $\gamma_4, \gamma_5 \geq 1$ such that, if $r \geq \gamma_4$ and if $x = S_0^{i,j} \notin B(r)$ under $\mathbf{Q}_{\mathcal{C}_0}$, then
\begin{equation} \mathbf{Q}_{\mathcal{C}_0} \big( T^{i,j}_{B(r)} < \infty \big) \leq \gamma_5 \left(\frac{r}{\|x\|}\right)^{d-2}.
\end{equation}

Let $\ell \geq 1$ and $s \in [t_{\ell-1}, t_\ell]$. Recall that $N (t) = |\{m \geq 1: \xi_m \leq t\}|$ denotes the number of returns to $\mathrm{Ref}^\times$ by time $t$. Since diameter grows at most linearly in time and since $\mathcal{V}_{\xi_{N(s)}}^i \in \mathrm{Ref}$ has a diameter of at most $2$,
\begin{equation} \mathrm{diam} (\mathcal{V}_s^i) \leq \xi_{N(s)+1} - \xi_{N(s)} + 2.
\end{equation}

Let $\alpha > 0$ be the constant named in Proposition~\ref{qg1}, let $\mathcal{C}_0 \in \mathrm{Ref}^\times$ satisfy $\mathrm{sep} (\mathcal{C}_0) \geq \alpha$, and let $\ell \geq 1$. By conditioning on $\mathscr{F}_{\eta_{\ell-1}}$ and then applying Proposition~\ref{qg1}, we find that
\begin{equation*}
\mathbf{Q}_{\mathcal{C}_0} \Big( \mathsf{G}(\ell)^{\mathsf{c}} \cap_{m=1}^{\ell-1} \mathsf{G} (m) \Big) \leq \mathbf{E}_{\mathcal{C}_0} \, \Big[ \mathbf{Q}_{\mathcal{C}_0} \big( \mathsf{G} (\ell)^{\mathsf{c}} \mid \mathscr{F}_{\eta_{\ell-1}} \big) \mathbf{1}_{\mathsf{G} (\ell-1)}  \Big] \leq 8\ell^{-2}. 
\end{equation*}

First, $\mathsf{F}_1^{i,j} (\ell) \subseteq \mathsf{G}_1^{i,j} (\ell)$ holds because
\begin{align*}
\mathsf{F}_1^{i,j} &= \left\{ \exists s \in (t_{\ell-1},t_\ell]: \| S_{N(s)}^{i,j} \| \geq 2^\ell \epsilon_\ell^{-1} a + 6 \kappa_\ell^2 \right\}\\ 
&\subseteq \left\{ \exists s \in (t_{\ell-1},t_\ell]: \mathrm{dist}(\mathcal{V}_s^i,\mathcal{V}_s^j) \geq 2^\ell \epsilon_\ell^{-1} a \right\} = \mathsf{G}_1^{i,j}.
\end{align*}

Second, the inclusion $\mathsf{F}_2^{i,j} (\ell) \subseteq \mathsf{G}_2^{i,j}$ is justified by
\begin{align*}
\mathsf{F}_2^{i,j} (\ell) &\subseteq \left\{\|S_{N(s)}^{i,j}\| \geq 2^{\ell-1} \epsilon_\ell a + 6 \kappa_\ell^2, \,\, s \in [t_{\ell-1},t_\ell]\right\}\\ 
&\subseteq \left\{ \mathrm{dist} (\mathcal{V}_s^i, \mathcal{V}_s^j) \geq 2^{\ell-1}\epsilon_\ell a, \,\, s \in [t_{\ell-1},t_\ell] \right\} = \mathsf{G}_2^{i,j} (\ell).
\end{align*}

Third, $\mathsf{F}_3^{i,j} (\ell) \subseteq \mathsf{G}_3^{i,j} (\ell)$ holds because the reasoning that led to the first inclusion also shows that $\rho_\ell^{i,j} \leq N(\sigma_\ell^{i,j})$, hence
\begin{align*}
\mathsf{F}_3^{i,j} (\ell) &=\left\{ \|S_{m}^{i,j}\| \geq 2^\ell a + 6 \kappa_\ell^2, \,\, m \in [\rho_\ell^{i,j}, N(t_\ell)+1] \right\}\\ 
&\subseteq \left\{ \|S_{N(s)}^{i,j}\| \geq 2^\ell a + 6 \kappa_\ell^2, \,\, s \in [\sigma_\ell^{i,j}, t_\ell] \right\}\\ 
& \subseteq \left\{ \mathrm{dist} (\mathcal{V}_s^i, \mathcal{V}_s^j) \geq 2^\ell a, \,\, s \in [\sigma_\ell^{i,j}, t_\ell] \right\} = \mathsf{G}_3^{i,j} (\ell).
\end{align*}

We use \eqref{f4 claim} to prove \eqref{t bef n eq} as
\begin{align*}
\mathbf{Q}_{\mathcal{C}_0} \left( \mathsf{F}_1^{i,j} (\ell)^{\mathsf{c}} \cap \mathsf{F}_4 (\ell) \bigm\vert \mathscr{F}_{\eta_{\ell-1}} \right) &\leq \mathbf{Q}_{\mathcal{C}_0} \left( S_{N(t_{\ell-1}) + 1 + m}^{i,j} \in B(r), \,\, 0 \leq m \leq \lambda r^2 \bigm\vert \mathscr{F}_{\eta_{\ell-1}} \right)\\ 
&= \mathbf{Q}_{\mathcal{V}_{\eta_{\ell-1}}} \left( T^{i,j}_{B(r)^{\mathsf{c}}} > \lambda r^2 \right) \leq \gamma_2 e^{-\gamma_3 \lambda}  = (8n\ell)^{-2}.
\end{align*}
The first inequality follows from the definition of $\mathsf{F}_1^{i,j} (\ell)^{\mathsf{c}}$ and the claimed bound on $N(t_\ell)-N(t_{\ell-1})-1$; the first equality is due to the strong Markov property at time $\eta_{\ell-1}$; the second inequality holds by \eqref{esc time}, which applies because $\mathcal{V}_{\eta_{\ell-1}} \in \mathrm{Ref}^\times$; and the second equality holds by the choice of $\lambda$.

For $\mathsf{F}_2^{i,j} (\ell)$ to occur, it suffices for the random walk from $S^{i,j}_{N(t_{\ell-1})}$ to never hit $B(r)$. In fact, when $\mathsf{G} (\ell-1)$ occurs, $S^{i,j}_{N(t_{\ell-1})} \in B(r)^{\mathsf{c}}$, so we can consider the random walk from $X = S^{i,j}_{N(t_{\ell-1})+1}$ instead. This is a minor point, so we discuss it at the end of the proof. For now, we simply use the inclusion  
\begin{equation} F_2^{i,j} (\ell) \cap \mathsf{G}(\ell-1) \supseteq \left\{ S_m^{i,j} \in B(r)^{\mathsf{c}}, \,m > N(t_{\ell-1})\right\} \cap \mathsf{G}(\ell-1).
\end{equation}

By \eqref{f2 incl}, the strong Markov property at $\eta_{\ell-1}$, and \eqref{avoid}, when $\mathsf{G} (\ell-1)$ occurs, 
\begin{align}
\mathbf{Q}_{\mathcal{C}_0} \left( \mathsf{F}_2^{i,j} (\ell) \bigm\vert \mathscr{F}_{\eta_{\ell-1}} \right) 
&\geq \mathbf{Q}_{\mathcal{C}_0} \left( S_m^{i,j} \in B(r)^{\mathsf{c}}, \,m > N(t_{\ell-1}) \bigm\vert \mathscr{F}_{\eta_{\ell-1}} \right) \nonumber\\ 
&= \mathbf{Q}_{\mathcal{V}_{\eta_{\ell-1}}} \left( T_{B(r)^{\mathsf{c}}}^{i,j} = \infty \right) \geq 1 - \gamma_5 \Big( \frac{r}{\|X\|} \Big)^{d-2}. \end{align}
Our use of \eqref{avoid} relies on the fact that $\mathcal{V}_{\eta_{\ell-1}} \in \mathrm{Ref}^\times$ and requies that we take $a$ sufficiently large to ensure that $r \geq \gamma_4$.

To bound below $\|X\|$, we note that the separation of $\mathcal{V}_{\eta_{\ell-1}}$ is at least $2^{\ell-1} a$, while the diameters of the clusters are at most $2$, when $\mathsf{G} (\ell-1)$ occurs. By \eqref{tri app both},
\begin{equation} \| X \| \geq \mathrm{dist} (\mathcal{V}_{\eta_{\ell-1}}^i,\mathcal{V}_{\eta_{\ell-1}}^j) - \mathrm{diam} (\mathcal{V}_{\eta_{\ell-1}}^i) - \mathrm{diam} (\mathcal{V}_{\eta_{\ell-1}}^j) \geq 2^{\ell-1} a - 4.
\end{equation}

By the strong Markov property at time $\xi_m$ and \eqref{avoid},
\begin{align*}
\mathbf{Q}_{\mathcal{C}_0} \big( \mathsf{F}_1^{i,j} (\ell) \cap \mathsf{F}_3^{i,j} (\ell)^{\mathsf{c}} \bigm\vert \mathscr{F}_{\eta_{\ell-1}} \big)
&= \mathbf{E}_{\mathcal{V}_{\eta_{\ell-1}}} \Big[ \mathbf{Q}_{\mathcal{V}_{\xi_m}} \big( \mathsf{F}_3^{i,j} (\ell)^{\mathsf{c}} \big); \mathsf{F}_1^{i,j} (\ell) \Big] \\  
&\leq \mathbf{E}_{\mathcal{V}_{\eta_{\ell-1}}} \Big[ \gamma_5 \Big( \frac{r}{\| Y \|} \Big)^{d-2} \Big] \leq \gamma_5 \Big( \frac{r}{R} \Big)^{d-2}.
\end{align*}

By Proposition~\ref{h sub g} and a union bound over distinct pairs of clusters, we have
\begin{equation} \mathbf{Q}_{\mathcal{C}_0} \left( \mathsf{G} (\ell)^{\mathsf{c}} \mid \mathscr{F}_{\eta_{\ell-1}} \right) \leq \mathbf{Q}_{\mathcal{C}_0} \left( \mathsf{F} (\ell)^{\mathsf{c}} \mid \mathscr{F}_{\eta_{\ell-1}} \right) \leq \sum_{i < j} \mathbf{Q}_{\mathcal{C}_0} \left( \mathsf{F}^{i,j} (\ell)^{\mathsf{c}} \mid \mathscr{F}_{\eta_{\ell-1}} \right).
\end{equation}

Using the fact that, for events $E_1$ and $E_2$, $E_2^{\mathsf{c}}$ is contained in the disjoint union $( E_1 \cap E_2^{\mathsf{c}} ) \cup E_1^{\mathsf{c}}$, we find that
\begin{multline*}
\mathbf{Q}_{\mathcal{C}_0} \left( \mathsf{F}^{i,j} (\ell)^{\mathsf{c}} \bigm\vert \mathscr{F}_{\eta_{\ell-1}} \right) \leq 3 \mathbf{Q}_{\mathcal{C}_0} \left( \mathsf{F}_4 (\ell)^{\mathsf{c}} \bigm\vert \mathscr{F}_{\eta_{\ell-1}} \right) + 2 \mathbf{Q}_{\mathcal{C}_0} \left( \mathsf{F}_1^{i,j} (\ell)^{\mathsf{c}} \cap \mathsf{F}_4 (\ell) \bigm\vert \mathscr{F}_{\eta_{\ell-1}} \right)\\  
+ \mathbf{Q}_{\mathcal{C}_0} \left( \mathsf{F}_2^{i,j} (\ell)^{\mathsf{c}} \bigm\vert \mathscr{F}_{\eta_{\ell-1}} \right) + \mathbf{Q}_{\mathcal{C}_0} \left( \mathsf{F}_1^{i,j} (\ell) \cap \mathsf{F}_3^{i,j} (\ell)^{\mathsf{c}} \bigm\vert \mathscr{F}_{\eta_{\ell-1}} \right).
\end{multline*}

Indeed, it would take only two ``stages'':
\begin{enumerate}
\item[(1')] First, we rearrange $V$ into a line segment emanating in the $-e_1$ direction from, say, the element of $V$ which is least in the lexicographic ordering of $\mathbb{Z}^d$.
\item[(2')] Second, we ``treadmill'' (Figures~\ref{treadmill} and \ref{treadmill2}) a pair of elements from the ``tip'' of the segment, in the $-e_1$ direction, until the pair is sufficiently far from the other elements. We then repeat this process, one pair at a time, until only two or three elements of the initial segment remain.
\end{enumerate}

Here is the three-stage procedure, which takes as input $V \in \mathrm{Conf}_{d,n}$ and an integer $a \geq 1$, which we will later require to be sufficiently large in terms of $d$ and $n$. Note that the output of each algorithm is an element of $\mathrm{Conf}_{d,n}^\times$, not an element of $\mathrm{Conf}_{d,n}$.
\begin{enumerate}
\item First, we will use Algorithm $\mathcal{A}_{\ref{alg1}}$ to construct a clustering $\mathcal{C} = \mathcal{A}_{\ref{alg1}} (V,a)$ of a configuration which can be lined-up with separation $dn^2 a$. This algorithm is the most complicated of the three. In brief, the algorithm repeatedly attempts to create a non-isolated lex element of a cluster, so that it can be ``treadmilled'' in the $-e_1$ direction---along with a neighboring element---to form a new dimer cluster. 
\item In the second stage, we will apply Algorithm $\mathcal{A}_{\ref{alg2}}$ to ``line-up'' the elements of each cluster $\mathcal{C}^i$. Specifically, in terms of the line segment
\begin{equation} L_k = \big\{ -j e_1: j \in \{0,1,\dots,k-1\} \big\}, \quad k \geq 1,
\end{equation}
we will rearrange the elements of $\mathcal{C}^i$ into the set $\mathrm{lex} (\mathcal{C}^i) + L_{|\mathcal{C}^i|}$. Specifically, the resulting clustering will be
\[ \mathcal{A}_{\ref{alg2}} (\mathcal{C}) = \left( \mathrm{lex} (\mathcal{C}^i) + L_{|\mathcal{C}^i|} \right)_{i=1}^{\# \mathcal{C}}.\]
\item In the third stage, Algorithm $\mathcal{A}_{\ref{alg3}}$ will iteratively treadmill pairs of elements from each segment in the $-e_1$ direction for multiples of $a$ steps until only a dimer or a trimer of the original segment remains (Figure~\ref{treadmill2}). The resulting clustering $\mathcal{A} (V,a) = \mathcal{A}_{\ref{alg3}} (\mathcal{A}_{\ref{alg2}} (\mathcal{C}), a)$ will be an $(a,1)$ DOT clustering.
\end{enumerate}

If $\Gamma'$ does not intersect $A$, then we are done, as $\Gamma'$ is contained in the union of $\Gamma$ and $\cup_i \partial_{\mathrm{vis}} B_i$, and because $\cup_i \partial_{\mathrm{vis}} B_i$ has at most $3^d |A|$ elements. Accordingly,
\begin{equation} |\Gamma'| \leq \sqrt{d} \mathrm{diam} (A) + 2d + 3^d |A| \leq \sqrt{d}\, \mathrm{diam} (A) + 3^{d+1} |A|.
\end{equation}

